import pytest
from requests.exceptions import HTTPError

@pytest.mark.parametrize("auth_type", ["api_key", "oauth2_token", "invalid_api_key"])
def test_user_logout(api_client, config, valid_api_key, invalid_api_key, oauth2_token, auth_type):
    """
    Test the /user/logout endpoint for various authentication methods.
    Covers valid authentication, invalid authentication, and authentication absence.
    """
    endpoint = "/user/logout"

    # Determine headers based on auth type
    if auth_type == "api_key":
        headers = {"Authorization": f"Bearer {valid_api_key}"}
    elif auth_type == "oauth2_token":
        headers = {"Authorization": f"Bearer {oauth2_token}"}
    elif auth_type == "invalid_api_key":
        headers = {"Authorization": f"Bearer {invalid_api_key}"}
    else:
        headers = {}  # Missing authentication

    try:
        # Perform the GET request
        response = api_client.get(endpoint, headers=headers)

        # Assert response codes based on authentication
        if auth_type in ["api_key", "oauth2_token"]:
            assert response.status_code == 200, f"Expected 200, got {response.status_code}"
            assert (
                response.text == "successful operation"
            ), f"Expected 'successful operation', got {response.text}"
        elif auth_type == "invalid_api_key":
            assert response.status_code == 401, f"Expected 401, got {response.status_code}"
        else:
            assert response.status_code == 403, f"Expected 403, got {response.status_code}"
    except HTTPError as http_err:
        pytest.fail(f"HTTP error occurred: {http_err}")
    except Exception as err:
        pytest.fail(f"Unexpected error occurred: {err}")
